import math

def _normalize_deg(d):
    return ((d + 180.0) % 360.0) - 180.0

def verifier(assign):
    # Basic presence and type validation
    required = ['thetas_deg', 'a_list', 'b_list', 'deltas_deg', 'k_mult']
    for key in required:
        if key not in assign:
            # Missing data
            return False, None  # Missing required key
    thetas = assign['thetas_deg']
    a_list = assign['a_list']
    b_list = assign['b_list']
    deltas = assign['deltas_deg']
    k_mult = assign['k_mult']

    # Domain checks
    if not (isinstance(thetas, list) and isinstance(a_list, list) and isinstance(b_list, list) and isinstance(deltas, list)):
        return False, None  # Lists required
    n = len(thetas)
    if not (len(a_list) == n and len(b_list) == n and len(deltas) == n):
        return False, None  # Length mismatch
    if n < 3:
        return False, None  # Must have multiple blocks for difficulty
    if not isinstance(k_mult, int) or k_mult <= 0:
        return False, None  # Invalid multiplier

    # Enforce nontriviality: at least two distinct step angles
    try:
        if len(set(int(t) for t in thetas)) < 2:
            return False, None
    except Exception:
        return False, None

    # Verify common-phase alignment to ensure structured difficulty
    try:
        Qs = []
        for theta, a, b, delta in zip(thetas, a_list, b_list, deltas):
            # All inputs should be numeric
            if not (isinstance(theta, (int, float)) and isinstance(a, int) and isinstance(b, int) and isinstance(delta, (int, float))):
                return False, None
            if b < a:
                return False, None
            Qj = delta + (a + b) * (theta / 2.0)
            Qj = _normalize_deg(Qj)
            Qs.append(Qj)
        # Check all Qj are equal modulo 360 within tolerance
        Q0 = Qs[0]
        for Qj in Qs[1:]:
            diff = _normalize_deg(Qj - Q0)
            if abs(diff) > 1e-7:
                return False, None
    except Exception:
        return False, None

    # Compute sums
    def rad(x):
        return math.radians(x)
    num = 0.0
    den = 0.0
    for theta, a, b, delta in zip(thetas, a_list, b_list, deltas):
        # Check angles are reasonable and blocks non-empty
        if theta <= 0 or a <= 0 or b <= 0:
            return False, None
        for k in range(a, b + 1):
            ang = k * theta + delta
            r = rad(ang)
            num += math.cos(r)
            den += math.sin(r)
    if abs(den) < 1e-12:
        return False, None
    x = num / den

    # Additional difficulty enforcement: ensure answer magnitude is not tiny
    val = k_mult * x
    # Avoid floating-point edge rounding by adding a tiny negative epsilon before floor
    answer = math.floor(val - 1e-12)
    return True, answer
